package com.lyrashop.order.entity;import java.time.Instant;import java.util.UUID;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;import jakarta.persistence.*;
@Entity @Table(name="tracking_events") public class TrackingEvent{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@JdbcTypeCode(SqlTypes.BINARY)@Column(name="order_id",length=16)private UUID orderId;private String status;private String description;private String location;@Column(name="occurred_at")private Instant occurredAt;protected TrackingEvent(){}public TrackingEvent(UUID o,String s,String d,String l,Instant at){orderId=o;status=s;description=d;location=l;occurredAt=at;}public Long getId(){return id;}public String getStatus(){return status;}public String getDescription(){return description;}public String getLocation(){return location;}public Instant getOccurredAt(){return occurredAt;}}
